mapper.select:
select obp.*,cc.con_name conName,sc.c_name unitName,pp.P_Name as pName from osm_breach_penalty obp
left join Pre_Project pp  on obp.p_id=pp.P_Id
left join Con_Contract cc  on obp.con_id=cc.Con_Id
left JOIN SYS_Company sc on sc.C_ID=obp.unit_id

    
        and obp.punish_item_name like concat('%',#{params.punishItemName},'%')
    
    
        and obp.item_type = #{params.itemType}
    
    
        and obp.p_id = #{params.pId}
    
    
        
            
                and likePname(#{params.pName},pp.P_Id)=true
            
            
                and pp.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        
            
                and likePname(#{params.pName},pp.P_Id)=true
            
            
                and pp.P_Name like concat('%',#{params.pname},'%')
            
        
    
    
        and obp.con_id = #{params.conId}
    
    
        and cc.con_name like concat('%',#{params.conName},'%')
    
    
        and cc.Con_Id = #{params.conId}
    
    
        and sc.c_id = #{params.unitId}
    
    
        
            
                and likeCname(#{params.exContractorName},sc.C_Id)=true
            
            
                and sc.c_name like concat('%',#{params.cName},'%')
            
        
    
    
        and obp.using_seals = #{params.usingSeals}
    
    
        and obp.seals_type = #{params.sealsType}
    
    
        and obp.state = #{params.state}
    
    
        and obp.handler_user_name like concat('%',#{params.handlerUserName},'%')
    
    
        and obp.create_uname like concat('%',#{params.createUname},'%')
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by obp.Create_Time DESC
